export const SCENE_STYLES = styles.map(([id, label, keywords, names]) => ({ id, label, keywords, scenes: names.split("、").map((name, i) => ({ id: `${id}-${i + 1}`, name, styleId: id, style: label, keywords, description: `${label}的${name}，${keywords}；背景服务于人物与商品展示，留出清晰活动空间，避免杂物、文字和道具遮挡商品。` })) }));
export const SCENES = SCENE_STYLES.flatMap(s => s.scenes);
export const findScene = id => SCENES.find(s => s.id === id);
export function cleanSceneSelection(selection) {
  if (selection == null) return undefined;
  const scene = findScene(selection.sceneId);
  if (!scene) throw Object.assign(new Error("场景不存在，请从场景库重新选择"), { statusCode: 400 });
  return { sceneId: scene.id };
}
export function sceneInstructions(project) {
  if (project.sceneMode !== "keywords") return "";
  const scene = findScene(project.sceneSelection?.sceneId);
  if (!scene) throw new Error("请选择要写入脚本的场景关键词");
  return `用户已选场景（优先于参考视频与旧模板的背景）：${scene.style} / ${scene.name}。${scene.description} 全部脚本、关键帧和视频保持此场景，复用参考视频的动作、运镜与时长。场景变化不得改变人物身份、商品颜色、纹样或结构，不得增加视频时长。`;
}
export function sceneInputKey(project) {
  return JSON.stringify({ video: project.assets.video?.path, customInput: project.assets.customInput?.path, template: project.assets.reusableTemplate?.path, people: project.assets.modelImages.map(f => f.path), products: project.assets.productImages.map(f => f.path), cast: castFingerprint(project), modelMeasurements: project.modelMeasurements, productMeasurements: project.productMeasurements, notes: project.notes || "" });
}
